package com.assistant import com.assistant.diagnostic.RuntimeLogger import java.util.concurrent.ThreadLocalRandom import java.util.concurrent.atomic.AtomicBoolean object NativeBridge { private const val LIBRARY = "splendor_native" private val nativeReady = AtomicBoolean(false) @Volatile private var nativeFailure = "" @Volatile private var failureLogged = false init { try { System.loadLibrary(LIBRARY) nativeReady.set(true) RuntimeLogger.log( "NativeBridge: splendor_native loaded; explicit JNI registration active", "RUNTIME" ) } catch (t: Throwable) { nativeFailure = "${t.javaClass.simpleName}: ${t.message ?: "unknown"}" logFailureOnce() } } @JvmStatic fun nativeKickingPosture( carrierX: Float, carrierY: Float, carrierVx: Float, carrierVy: Float, targetX: Float, targetY: Float, pitchWidth: Float, pitchHeight: Float, outBuffer: FloatArray ) { if (outBuffer.size < 4) return if (nativeReady.get()) { try { nativeKickingPostureImpl( carrierX, carrierY, carrierVx, carrierVy, targetX, targetY, pitchWidth, pitchHeight, outBuffer ) return } catch (t: Throwable) { nativeReady.set(false) nativeFailure = "${t.javaClass.simpleName}: ${t.message ?: "unknown"}" logFailureOnce() } } outBuffer[0] = targetX.coerceIn(0f, pitchWidth.coerceAtLeast(0f)) outBuffer[1] = targetY.coerceIn(0f, pitchHeight.coerceAtLeast(0f)) outBuffer[2] = 1f outBuffer[3] = 0f } @JvmStatic fun nativeAgilityPhysics( playerVelocity: Float, opponentDistance: Float, movementAngleDegrees: Float, possessionConfidence: Float, turnIntensity: Float, playerX: Float, playerY: Float, oppX: Float, oppY: Float, threadSeed: Int, outBuffer: FloatArray ) { if (outBuffer.size < 6) return if (nativeReady.get()) { try { nativeAgilityPhysicsImpl( playerVelocity, opponentDistance, movementAngleDegrees, possessionConfidence, turnIntensity, playerX, playerY, oppX, oppY, threadSeed, outBuffer ) return } catch (t: Throwable) { nativeReady.set(false) nativeFailure = "${t.javaClass.simpleName}: ${t.message ?: "unknown"}" logFailureOnce() } } outBuffer[0] = 1.5f outBuffer[1] = possessionConfidence.coerceIn(0f, 1f) outBuffer[2] = 0f outBuffer[3] = 0f outBuffer[4] = 45f outBuffer[5] = 0f } @JvmStatic fun nextThreadSeed(): Int = ThreadLocalRandom.current().nextInt() @JvmStatic fun isNativeAvailable(): Boolean = nativeReady.get() @JvmStatic fun nativeFailure(): String = nativeFailure private fun logFailureOnce() { synchronized(this) { if (failureLogged) return failureLogged = true } try { RuntimeLogger.log( "NATIVE LINK FAILURE: $LIBRARY unavailable; deterministic Kotlin fallback active; $nativeFailure", "RUNTIME" ) } catch (_: Throwable) {} } @JvmStatic private external fun nativeKickingPostureImpl( carrierX: Float, carrierY: Float, carrierVx: Float, carrierVy: Float, targetX: Float, targetY: Float, pitchWidth: Float, pitchHeight: Float, outBuffer: FloatArray ) @JvmStatic private external fun nativeAgilityPhysicsImpl( playerVelocity: Float, opponentDistance: Float, movementAngleDegrees: Float, possessionConfidence: Float, turnIntensity: Float, playerX: Float, playerY: Float, oppX: Float, oppY: Float, threadSeed: Int, outBuffer: FloatArray ) } 